mapper.select:
select * from user_account where 1=1

  and (phone like concat('%',#{keyword},'%') or username like concat('%',#{keyword},'%') or nickname like concat('%',#{keyword},'%') or full_name like concat('%',#{keyword},'%') or id_card_no like concat('%',#{keyword},'%'))

 and role = #{role}
 and status = #{status}
order by id desc

mapper.update:
update user_account
set nickname=#{nickname}, full_name=#{fullName}, id_card_no=#{idCardNo}, scenic_id=#{scenicId}, role=#{role}, updated_at=now()
where id=#{id}

